JavaScript:
var greenworks = null;
try{
  greenworks = require('./js/greenworks/greenworks'); //path to your greenworks.js
  greenworks.init();
}catch(ex){
  console.log(ex);
  greenworks = null;
};

function ActiveAchievement(achievement, success_callback, error_callback){
  try{
    success_callback = success_callback||function(){};
    error_callback = error_callback||function(){};
    greenworks.activateAchievement(achievement, success_callback, error_callback);
  }catch(ex){
    console.log('failed to active achievement: ', achievement);
    console.log(ex);
  }
}

